import java.util.Scanner;

public class UserThreadPriority implements Runnable {
    private String k;
    private char c;
    private Thread thread;

    public UserThreadPriority(String k, char c) {
        this.k = k;
        this.c = c;
        this.thread = new Thread(this);
    }

    public void run() {
        System.out.println("Thread name: " + thread.getName());
        System.out.println("String: " + k);
        System.out.println("Character: " + c);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String k = scanner.nextLine();
        System.out.print("Enter a character: ");
        char c = scanner.next().charAt(0);

        UserThreadPriority threadobj1 = new UserThreadPriority(k, c);
        UserThreadPriority threadobj2 = new UserThreadPriority(k, c);

        threadobj1.thread.setName("ThreadA");
        threadobj2.thread.setName("ThreadB");

        threadobj1.thread.start();
        threadobj2.thread.start();
    }
}
